import { transformFileAsync } from '@babel/core';
import { createEs2015LinkerPlugin } from '@angular/compiler-cli/linker/babel';
import { ConsoleLogger, NodeJSFileSystem, LogLevel } from '@angular/compiler-cli';
import { globSync } from 'node:fs';
const plugin = createEs2015LinkerPlugin({ fileSystem: new NodeJSFileSystem(), logger: new ConsoleLogger(LogLevel.warn), linkerJitMode: false, unknownDeclarationVersionHandling: 'error' });
let n = 0;
for (const f of globSync('node_modules/@wolsok/thanos/esm2022/**/*.js')) {
  const r = await transformFileAsync(f, { plugins: [plugin], configFile: false, babelrc: false });
